3	/**
4	 * Luhn check digit for an owner's {@code customerCode}. A single digit (0-9) computed over the
5	 * decimal digits contained in the customer code (non-digit characters such as the hyphen separators
6	 * are ignored), using the standard Luhn algorithm. Derived purely from the owner's own
7	 * {@code customerCode}, so it carries no stored state and is seed-independent. Used by the owner
8	 * mapper to expose {@code checkDigit} on responses.
9	 */
10	public final class CheckDigit {
11	
12	    private CheckDigit() {
13	    }
14	
15	    /**
16	     * The Luhn check digit over the digits of the given customer code, or {@code null} when the
17	     * customer code is absent (e.g. legacy owners with no customer code).
18	     */
19	    public static Integer of(String customerCode) {
20	        if (customerCode == null) {
21	            return null;
22	        }
23	        int sum = 0;
24	        boolean dbl = true;
25	        for (int i = customerCode.length() - 1; i >= 0; i--) {
26	            char c = customerCode.charAt(i);
27	            if (c < '0' || c > '9') {
28	                continue;
29	            }
30	            int d = c - '0';
31	            if (dbl) {
32	                d *= 2;
33	                if (d > 9) {
34	                    d -= 9;
35	                }
36	            }
37	            sum += d;
38	            dbl = !dbl;
39	        }
40	        return (10 - (sum % 10)) % 10;
41	    }
42	}
