9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
15	 * canonical region derived from the owner's postcode (falling back to its city; see
16	 * {@link Locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
17	 * {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The telephone is normalized to
18	 * E.164 form (see {@link OwnerIdentity#normalizedTelephone(String)}), the same normalization used by
19	 * the identity key. The code carries no per-city sequence, so it is derived purely from the owner's
20	 * own fields and is seed-independent.
21	 *
22	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
23	 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
24	 * receive distinct customer codes.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Locality.of(owner.getPostcode(), owner.getCity());
30	        String hash8 = hash8(OwnerIdentity.normalizedTelephone(owner.getTelephone()), owner.getLastName());
31	        String base = region + "-" + hash8;
32	        owner.setCustomerCode(deduplicate(base, ownerRepository));
33	    }
34	
35	    /**
36	     * The base code if no existing owner already uses it, otherwise {@code base-<n>} with the
37	     * smallest {@code n} of 2 or more that is not already taken.
38	     */
39	    private static String deduplicate(String base, OwnerRepository ownerRepository) {
40	        Set<String> existing = new HashSet<>();
41	        for (Owner other : ownerRepository.findAll()) {
42	            String code = other.getCustomerCode();
43	            if (code != null) {
44	                existing.add(code);
45	            }
46	        }
47	        if (!existing.contains(base)) {
48	            return base;
49	        }
50	        for (int n = 2; ; n++) {
51	            String candidate = base + "-" + n;
52	            if (!existing.contains(candidate)) {
53	                return candidate;
54	            }
55	        }
56	    }
57	
58	    /** First 8 upper-case hex characters of SHA-256 over {@code (normalizedTelephone + lastName)}. */
59	    private static String hash8(String normalizedTelephone, String lastName) {
60	        String input = normalizedTelephone + (lastName == null ? "" : lastName);
61	        try {
62	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
63	            StringBuilder sb = new StringBuilder(8);
64	            // Two hex characters per byte, so four bytes yield the eight characters required.
65	            for (int i = 0; i < 4; i++) {
66	                sb.append(String.format("%02X", digest[i]));
67	            }
68	            return sb.toString();
69	        }
70	        catch (NoSuchAlgorithmException e) {
71	            throw new IllegalStateException("SHA-256 not available", e);
72	        }
73	    }
74	}
